#include <iostream>
#include <vector>
#include <stdexcept>
struct Guard {int& active;explicit Guard(int& n):active(n){++active;}Guard(const Guard&)=delete;Guard& operator=(const Guard&)=delete;~Guard(){--active;}};
class Store {std::vector<int> values_{1,2};public:
 void replace(bool fail,int& active){Guard g{active};auto candidate=values_;candidate.push_back(9);
  if(fail)throw std::runtime_error("injected");values_.swap(candidate);}
 int sum()const{int n=0;for(int x:values_)n+=x;return n;}
};
int main(){int mode;if(!(std::cin>>mode)||mode<0||mode>1){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 Store s;int active=0;try{s.replace(mode==1,active);std::cout<<"ok ";}catch(const std::runtime_error&){std::cout<<"rejected ";}
 std::cout<<s.sum()<<' '<<active<<'\n';}

