#include <iostream>
#include <memory>
#include <stdexcept>
struct Rule {virtual int apply(int n)const=0;virtual ~Rule()=default;};
struct Double final:Rule {int apply(int n)const override{if(n<0||n>100)throw std::out_of_range("value");return n*2;}};
int main(){int n;if(!(std::cin>>n)){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::unique_ptr<Rule> policy=std::make_unique<Double>();int saved=7;
 try{int candidate=policy->apply(n);saved=candidate;std::cout<<"ok ";}catch(const std::out_of_range&){std::cout<<"rejected ";}
 std::cout<<saved<<'\n';}

